package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.os.*;import android.view.*;import java.io.*;
/** Visual fixture only. Controls cannot start playback or alter system volume in preview. */
public final class MediaDashboardTests extends Instrumentation {
 private int count;private void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;}
 private Object get(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void capture(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"material-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 public void onCreate(Bundle b){start();}public void onStart(){final Context c=getTargetContext();Bundle result=new Bundle();Activity activity=null;PlaybackService before=PlaybackService.instance;boolean fm=FmService.playing;AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);int volume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);final String previousTitle=PlaybackService.title,previousState=PlaybackService.state;try{check(Appearance.THEMES.length==Appearance.COLORS.length&&Appearance.THEMES[9].contains("Material"),"material palette available");check(BackupEngine.allowed("appearance","app-theme-NowPlayingActivity","int"),"media theme accepted by settings backup");activity=startActivitySync(new Intent(c,NowPlayingActivity.class).putExtra("preview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity a=activity;runOnMainSync(new Runnable(){public void run(){try{java.lang.reflect.Field f=a.getClass().getDeclaredField("source");f.setAccessible(true);f.setInt(a,0);((View)a.getWindow().getDecorView()).invalidate();}catch(Exception e){throw new RuntimeException(e);}}});for(int i=0;i<30&&!activity.hasWindowFocus();i++)SystemClock.sleep(100);capture("music");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check((Boolean)get(activity,"previewPlaying"),"OK toggles dashboard fixture");sendKeyDownUpSync(KeyEvent.KEYCODE_STAR);waitForIdleSync();check((Integer)get(activity,"source")==1,"star changes to radio source");capture("fm");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();check((Integer)get(activity,"previewVolume")==7&&audio.getStreamVolume(AudioManager.STREAM_MUSIC)==volume,"demo volume is isolated");check(PlaybackService.instance==before&&FmService.playing==fm,"demo controls do not start real media");final Activity dashboard=activity;runOnMainSync(new Runnable(){public void run(){dashboard.finish();}});waitForIdleSync();activity=null;Paint paint=new Paint(3);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(16);String[] lines=MusicFace.titleLines("O piesă cu un titlu foarte lung și diacritice",paint,110);check(!lines[0].isEmpty()&&paint.measureText(lines[0])<=110&&!lines[1].isEmpty(),"music title wraps within card width");if(before==null){runOnMainSync(new Runnable(){public void run(){PlaybackService.title="Lumini de seară";PlaybackService.state="DEMO · fără redare";}});activity=startActivitySync(new Intent(c,MediaActivity.class).putExtra("now",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<30&&!activity.hasWindowFocus();i++)SystemClock.sleep(100);check(get(activity,"face") instanceof MusicFace,"native music face installed");capture("player");sendKeyDownUpSync(KeyEvent.KEYCODE_4);sendKeyDownUpSync(KeyEvent.KEYCODE_5);sendKeyDownUpSync(KeyEvent.KEYCODE_6);check(PlaybackService.instance==null,"empty-session music shortcuts do not start audio");}result.putString("result","PASS "+count+" media dashboard/player checks; silent visual fixtures");}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{runOnMainSync(new Runnable(){public void run(){PlaybackService.title=previousTitle;PlaybackService.state=previousState;}});if(activity!=null){final Activity a=activity;runOnMainSync(new Runnable(){public void run(){a.finish();}});}}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
